CREATE TABLE organizations (id BIGSERIAL PRIMARY KEY, name VARCHAR(160) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE users (id BIGSERIAL PRIMARY KEY, organization_id BIGINT NOT NULL REFERENCES organizations(id), email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(32) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE buildings (id BIGSERIAL PRIMARY KEY, organization_id BIGINT NOT NULL REFERENCES organizations(id), name VARCHAR(160) NOT NULL, location VARCHAR(255), building_type VARCHAR(80), occupancy INTEGER NOT NULL DEFAULT 0, operating_hours NUMERIC(5,2) NOT NULL DEFAULT 8, latitude NUMERIC(9,6), longitude NUMERIC(9,6), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE consumption_records (id BIGSERIAL PRIMARY KEY, organization_id BIGINT NOT NULL REFERENCES organizations(id), building_id BIGINT NOT NULL REFERENCES buildings(id), recorded_at TIMESTAMPTZ NOT NULL, electricity_kwh NUMERIC(14,3) NOT NULL DEFAULT 0, water_liters NUMERIC(14,3) NOT NULL DEFAULT 0, waste_kg NUMERIC(14,3) NOT NULL DEFAULT 0, cost_inr NUMERIC(14,2) NOT NULL DEFAULT 0, co2_kg NUMERIC(14,3) NOT NULL DEFAULT 0, source VARCHAR(40) NOT NULL DEFAULT 'MANUAL', import_key VARCHAR(255) NOT NULL UNIQUE);
CREATE TABLE data_imports (id BIGSERIAL PRIMARY KEY, organization_id BIGINT NOT NULL REFERENCES organizations(id), filename VARCHAR(255) NOT NULL, received_count INTEGER NOT NULL, imported_count INTEGER NOT NULL, duplicate_count INTEGER NOT NULL, invalid_count INTEGER NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE alerts (id BIGSERIAL PRIMARY KEY, organization_id BIGINT NOT NULL REFERENCES organizations(id), building_id BIGINT REFERENCES buildings(id), type VARCHAR(80) NOT NULL, severity VARCHAR(20) NOT NULL, message TEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'OPEN', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), resolved_at TIMESTAMPTZ);
CREATE TABLE audit_logs (id BIGSERIAL PRIMARY KEY, organization_id BIGINT NOT NULL REFERENCES organizations(id), user_id BIGINT REFERENCES users(id), action VARCHAR(120) NOT NULL, details TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_consumption_org_time ON consumption_records(organization_id, recorded_at);
CREATE INDEX idx_consumption_building_time ON consumption_records(building_id, recorded_at);
CREATE INDEX idx_alerts_org_status ON alerts(organization_id, status);
